package com.civicpulse.controller;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.file.*;
@RestController @RequestMapping("/api/media") public class StoredMediaController {private final Path root;public StoredMediaController(@Value("${app.upload-dir:./uploads}") String dir){root=Paths.get(dir).toAbsolutePath().normalize();}@GetMapping("/{name}") public ResponseEntity<Resource> get(@PathVariable String name){try{Path p=root.resolve(name).normalize();if(!p.startsWith(root)||!Files.exists(p))return ResponseEntity.notFound().build();Resource r=new UrlResource(p.toUri());String ct=Files.probeContentType(p);return ResponseEntity.ok().contentType(MediaType.parseMediaType(ct==null?"application/octet-stream":ct)).body(r);}catch(Exception e){return ResponseEntity.notFound().build();}}}
